from dataclasses import dataclass
@dataclass(frozen=True)
class ByteRange:
    start: int
    end: int
    def valid(self, size: int) -> bool: return 0 <= self.start <= self.end <= size
    def contains(self, offset: int) -> bool: return self.start <= offset <= self.end
def utf8_boundary(data: bytes, offset: int) -> bool:
    if not 0 <= offset <= len(data): return False
    try: data[:offset].decode("utf-8")
    except UnicodeDecodeError: return False
    return True
def line_bounds(text: str, offset: int) -> tuple[int, int]:
    start = text.rfind("\n", 0, offset) + 1; end = text.find("\n", offset)
    return start, len(text) if end < 0 else end
def apply_range(text: str, region: ByteRange, value: str) -> str:
    raw = text.encode("utf-8")
    if not region.valid(len(raw)) or not utf8_boundary(raw, region.start) or not utf8_boundary(raw, region.end): raise ValueError("invalid range")
    return (raw[:region.start] + value.encode("utf-8") + raw[region.end:]).decode("utf-8")
def nearby_lines(text: str, line: int, before: int, after: int) -> list[str]:
    rows = text.splitlines(); return rows[max(0,line-before):min(len(rows),line+after+1)]

