from dataclasses import dataclass, field
from hashlib import sha256
@dataclass
class BufferShadow:
    file_id: str
    text: str
    changedtick: int
    recent: list[dict[str, object]] = field(default_factory=list)
    def apply(self, start: int, end: int, value: str, tick: int) -> None:
        if tick <= self.changedtick or not 0 <= start <= end <= len(self.text): raise ValueError("invalid buffer change")
        old=self.text; self.text=old[:start]+value+old[end:]; self.changedtick=tick
        self.recent.append({"start":start,"end":end,"value":value}); self.recent=self.recent[-64:]
    def digest(self) -> str: return sha256(self.text.encode("utf-8")).hexdigest()
    def snapshot(self) -> tuple[str,int,str]: return self.text,self.changedtick,self.digest()
    def unchanged(self,tick:int,digest:str)->bool: return self.changedtick==tick and self.digest()==digest
    def line_at(self,offset:int)->tuple[int,int,int]:
        start=self.text.rfind("\n",0,offset)+1; end=self.text.find("\n",offset)
        return start,len(self.text) if end<0 else end,self.text.count("\n",0,start)

