from dataclasses import dataclass
@dataclass(frozen=True)
class Change:
    start:int
    deleted:str
    inserted:str
@dataclass(frozen=True)
class UndoEntry:
    file_id:str
    before_version:int
    after_version:int
    change:Change
def apply_change(text:str,change:Change)->str:
    end=change.start+len(change.deleted)
    if text[change.start:end]!=change.deleted: raise ValueError("change base differs")
    return text[:change.start]+change.inserted+text[end:]
def reverse_change(change:Change)->Change:return Change(change.start,change.inserted,change.deleted)
def merge_adjacent(left:Change,right:Change)->Change|None:
    if left.start+len(left.inserted)==right.start:
        return Change(left.start,left.deleted+right.deleted,left.inserted+right.inserted)
    return None
def undo_entry(text:str,entry:UndoEntry,current_version:int)->tuple[str,int]:
    if current_version!=entry.after_version: raise ValueError("undo version changed")
    return apply_change(text,reverse_change(entry.change)),entry.before_version
def group_for_undo(changes:list[Change])->list[Change]:
    result=[]
    for change in changes:
        if result:
            merged=merge_adjacent(result[-1],change)
            if merged is not None: result[-1]=merged; continue
        result.append(change)
    return result
def commit_version(previous:int,change_count:int)->int:
    if change_count<0: raise ValueError("negative change count")
    return previous+int(change_count>0)

